// S4 Zusteller, minimal (Phase 1a): neue Objekte der letzten 24 Stunden als Telegram-Text (HTML), noch ohne Score.
// Regeln: nur Felder aus der Tabelle, keine Bewertung, kein Abruf. Telegram-Grenze 4096 Zeichen je Nachricht -> Teile.
const STUNDEN = 24;
const grenze = Date.now() - STUNDEN * 3600 * 1000;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const eur = n => (typeof n === 'number') ? n.toLocaleString('de-DE') + ' €' : 'k. A.';
const zahl = (n, e) => (typeof n === 'number') ? n.toLocaleString('de-DE') + e : 'k. A.';

const rows = $input.all().map(i => i.json).filter(j => j && j.objekt_schluessel && String(j.objekt_schluessel).startsWith('is24:'));
const neu = rows.filter(j => { const t = Date.parse(j.erfasst_am || ''); return Number.isFinite(t) && t >= grenze; });
neu.sort((a, b) => String(a.suchauftrag || '').localeCompare(String(b.suchauftrag || '')) || (a.preis_je_qm || 0) - (b.preis_je_qm || 0));

const datum = new Date().toLocaleDateString('de-DE', { timeZone: 'Europe/Berlin', weekday: 'short', day: '2-digit', month: '2-digit', year: 'numeric' });
const kopf = `<b>Immo-Digest ${esc(datum)}</b>\nNeu in den letzten ${STUNDEN} h: ${neu.length} (Bestand: ${rows.length}). Noch ohne Bewertung.`;

const zeilen = [];
let letzter = null;
for (const j of neu) {
  const sa = j.suchauftrag || 'ohne Suchauftrag';
  if (sa !== letzter) { zeilen.push(`\n<b>${esc(sa)}</b>`); letzter = sa; }
  const ort = [j.stadtteil, j.strasse].filter(x => x && x !== 'fehlt in der Anzeige').join(', ');
  const link = j.link ? `<a href="${esc(j.link)}">${esc(j.titel || j.objekt_schluessel)}</a>` : esc(j.titel || j.objekt_schluessel);
  zeilen.push(`• ${link}\n  ${esc(ort || 'Lage k. A.')} | ${eur(j.kaufpreis_eur)} | ${zahl(j.wohnflaeche_qm, ' m²')} | ${zahl(j.zimmer, ' Zi.')} | ${zahl(j.preis_je_qm, ' €/m²')}${j.provision_kaeufer_pct === 0 ? ' | provisionsfrei' : ''}`);
}

// In Nachrichten von max. 3900 Zeichen teilen (Reserve unter 4096)
const MAX = 3900;
const teile = [];
let akt = kopf;
for (const z of zeilen) {
  if ((akt + '\n' + z).length > MAX) { teile.push(akt); akt = z; } else { akt += '\n' + z; }
}
teile.push(akt);

return teile.map((text, i) => ({ json: { text, teil: i + 1, teile: teile.length, anzahl_neu: neu.length, anzahl_bestand: rows.length, schluessel: neu.map(j => j.objekt_schluessel) } }));
